from typing import Iterable, TypeVar, Dict

T = TypeVar('T')

def count_items(data: Iterable[T]) -> Dict[T, int]:
    """Return a dictionary mapping each unique item in data to its occurrence count."""
    result: Dict[T, int] = {}
    for item in data:
        if item in result:
            result[item] += 1
        else:
            result[item] = 1
    return result

